    lexicalNestingDepth++;
    objectNestingDepth++;
    atTopLevelInsideTraitOrObject = true;
    defsToMembers(defs);
    immediateDef = tparamsToLocals(tparams, immediateDef);

    accumulateMembersFromExtends(td);

    AbstractNode n = visitNodeTO(td);
    return n;
